// Guided lessons. Data, not UI: app.js walks these steps.
//
// lesson = { id, title, blurb, look, learned, steps }. `look` is one line over the canvas: what to look at. `learned` is shown when
// the last step is done.
// step = { mode, text?, exp?, hint?, deeper?, open?, look?, widget?, setup?: [[action, ...args]],
//          predict?: { q, choices, show?, run: [[action, ...]], answer(ctx), claims?, why(ctx), expects?, miss? } }
//   step.look overrides lesson.look; step.open lists folds to open: "poke" (controls), "code" (the Python), "try" (edit-and-run).
//   q is a string or (ctx) => string. show(choice, beginner) -> the label for a choice (plain words for beginners).
// Answers are COMPUTED from the real upstream code's output after the run, never hard-coded, so a vendor refresh can change a
// result without leaving a lesson that lies. The UI throws if answer() is not one of the choices. answer, claims and why may be async.
// miss = { wrongChoice: text }: what makes that wrong answer tempting. It is shown only while the computed answer is still
// `expects` (the answer the texts were written for) and every claim holds.
// ctx = { S, call }.
import { PLAIN_VERDICT, plainReason, runGrid, traceStats, modelName } from "./model.js";

const top = (r) => (r && r[0] ? r[0].path.split("/").pop().replace(/\.md$/, "") : "(nothing)");
const edit = (ctx, mode) => Object.entries(ctx.S.edits).find(([k]) => k.startsWith(mode + ":"))?.[1]?.out;
const head = (S, path) => (S.files[path] || "").split("\n").slice(0, 8).join("\n");
// only the lines rank() treats as a file's "head": title / name / description / tags / aliases / heading
const heading = (S, path) => head(S, path).split("\n").filter((l) => /^\s*(title|name|description|tags|aliases)\s*:|^#\s/.test(l)).join("\n");
const hitPaths = async (call, S, q) => [...new Set((await call("search", { files: S.files, query: q })).map((x) => x.path))];
const nFiles = (S, w) => Object.values(S.files).filter((t) => new RegExp(w, "i").test(t)).length;
const last = (S) => S.results.at(-1);
const lines = (out) => out.split("\n").filter(Boolean);
// simulated re-runs through the real gate (see lab_core.noise_sweep); the lesson uses the Gate scene's probes and thresholds
const noiseCache = new Map();  // answer(), claims and why() all ask for the same sweep; it is deterministic, so compute it once
export const noise = ({ call, S }, rw, rs, n) => {
  const args = { probes: S.gate.probes, rate_without: rw, rate_with: rs, samples: n, params: S.gate.params }, k = JSON.stringify(args);
  if (!noiseCache.has(k)) noiseCache.set(k, call("noise", args));
  return noiseCache.get(k);
};
const verdictLabel = (c, beg) => (beg ? PLAIN_VERDICT[c] : c);
const gateSays = (S) => (S.level === "beginner" ? plainReason(S.gate.res) : `${S.gate.res.verdict}: ${S.gate.res.reason}.`);
const skillSays = (S) => (S.level === "beginner" ? plainReason(S.skill.res.gate) : `${S.skill.res.gate.verdict}: ${S.skill.res.gate.reason}.`);
const BACKFILL = "facts/airflow-backfill-concurrency.md", ORD = "facts/orders-timestamps-utc.md";
const Q_ZONE = (search) => `- id: order-timezone\n  q: Which time zone are order timestamps stored in?\n  run: {search: ${search}}\n  expect: [UTC]\n  tier: must`;
// recorded model runs (web/runs.json): pick by skill, variant and model family, so a re-recording under new model ids still works
const run = (S, skill, variant, family) => Object.entries(S.runs?.meta.files || {}).find(([, m]) => m.skill === skill && (m.variant || null) === variant && m.model.includes(family))?.[0];
const runRes = (S, name) => S.runs.runs[name];
const dollars = (x) => `$${x.toFixed(3)}`;
const dstTrace = (S, family) => traceStats(runRes(S, run(S, "dst", null, family)));   // by name, not S.gate.run: q() is drawn before the step's setup has run
const modelOf = (S, name) => modelName(runRes(S, name).pi_args[1]);
const guardTextOf = (c) => (c.name === "read" ? c.args.path : c.args.command) ?? "";
const gk = (S) => S.guard.res.counts, gat = (S) => S.guard.att.counts;
const findRoot = (S) => S.guard.res.rows.filter((r, i) => r.outside && !r.blocked && /(^|[|;&]\s*)find\s+\/(\s|$)/.test(guardTextOf(S.guard.calls[i]))).length;
const nBash = (S) => S.guard.calls.filter((c) => c.name === "bash").length;
// q() is drawn once before the step's setup has run, so these tolerate "not computed yet"; the card is redrawn when setup is done
const sk = (S) => S.guard.out.res?.counts ?? { total: 0, dirty: 0, leaks: 0, fixed: 0, damaged: 0 }, sat = (S) => S.guard.out.att?.rows ?? [];
const REAL = ["root", "run_home", "cwd", "machine_home", "tmp", "tmp_parent"];
const armScore = (res, probe, arm) => res.rows.filter((r) => r.probe === probe && r.arm === arm && r.correct && r.finished !== false).length;
// The answer the Observability lessons read: in a model's `dst` run, the answer without the skill that made the most tool calls, and the
// answer with the skill to the same question and try. Chosen from the data, so a re-recording picks its own.
export const longestWithout = (res) => res.rows.filter((r) => r.arm === "without").reduce((a, r) => (!a || r.tools.length > a.tools.length ? r : a), null);
export function featured(S, family = "haiku", name) {
  name ??= run(S, "dst", null, family); const res = name && S.runs?.runs[name]; if (!res) return null;
  const wo = longestWithout(res);
  return wo && { run: name, without: wo, with: res.rows.find((r) => r.arm === "with" && r.probe === wo.probe && r.n === wo.n) };
}
const plural = (n, w) => `${n} ${w}${n === 1 ? "" : "s"}`, clean = (t) => String(t).replace(/`/g, "'").slice(0, 80);
const tlN = (S) => S.tl.calls.length, tlO = (S) => S.tl.labels.filter((x) => x.outside).length;
const logK = (S) => S.guard.live?.res?.counts, logStopped = (k) => k.ask + k.deny, logPct = (k) => Math.round((100 * logStopped(k)) / k.total);
const topRule = (S) => Object.entries(S.guard.live.res.rules).sort((a, b) => b[1] - a[1])[0];

// A case is one recorded story told through all three lenses. `skill`/`family` name its recorded run; its beats are in PILLARS.
export const CASES = [
  { id: "dst", title: "The agent that went looking for the answer", skill: "dst", family: "haiku", line: "A small model with no skill searched far beyond its folder. With the skill it made one call." },
  { id: "evidence", title: "The skill that helps, at a price", skill: "evidence-gated", family: "sonnet", line: "A skill that makes answers right, and costs nearly twice as much." },
  { id: "doubt", title: "The skill it read and still failed", skill: "doubt", family: "haiku", line: "The model opened the skill file. Its answers still missed what the check looks for." },
];
// The answer a case reads in the Trace mode, and its pair (same question, same try, other arm). dst and doubt: the without-skill answer with
// the most calls. evidence: the costliest with-skill answer. Chosen from the data, so a re-recording picks its own.
export function casePair(S, id) {
  const c = CASES.find((x) => x.id === id), name = c && run(S, c.skill, null, c.family), res = name && S.runs?.runs[name]; if (!res) return null;
  if (id !== "evidence") return featured(S, c.family, name);
  const wi = res.rows.filter((r) => r.arm === "with").reduce((a, r) => (!a || r.cost_usd > a.cost_usd ? r : a), null);
  return wi && { run: name, with: wi, without: res.rows.find((r) => r.arm === "without" && r.probe === wi.probe && r.n === wi.n) };
}
const callText = (S, i) => guardTextOf(S.guard.calls[i]);

